Color color(COLORREF rgb){return Color(255,GetRValue(rgb),GetGValue(rgb),GetBValue(rgb));}
Color mix(COLORREF a,COLORREF b,float t){return Color(255,BYTE(GetRValue(a)*(1-t)+GetRValue(b)*t),BYTE(GetGValue(a)*(1-t)+GetGValue(b)*t),BYTE(GetBValue(a)*(1-t)+GetBValue(b)*t));}
void path(GraphicsPath& p,RectF r,float radius){float d=std::min(radius*2,std::min(r.Width,r.Height));if(d<=0){p.AddRectangle(r);return;}p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.X+r.Width-d,r.Y,d,d,270,90);p.AddArc(r.X+r.Width-d,r.Y+r.Height-d,d,d,0,90);p.AddArc(r.X,r.Y+r.Height-d,d,d,90,90);p.CloseFigure();}
void rounded(Graphics& g,Color c,RectF r,float radius){GraphicsPath p;path(p,r,radius);SolidBrush b(c);g.FillPath(&b,&p);}
std::map<std::pair<float,bool>,std::unique_ptr<Font>>& fontCache(){static std::map<std::pair<float,bool>,std::unique_ptr<Font>> fonts;return fonts;}
void text(Graphics& g,const std::wstring& value,RectF r,float size,COLORREF rgb,bool bold=false,bool center=false){auto& font=fontCache()[{size,bold}];if(!font){FontFamily family(L"Segoe UI");font=std::make_unique<Font>(family.GetLastStatus()==Ok?&family:FontFamily::GenericSansSerif(),size,bold?FontStyleBold:FontStyleRegular,UnitPixel);}SolidBrush b(color(rgb));StringFormat f;f.SetAlignment(center?StringAlignmentCenter:StringAlignmentNear);f.SetLineAlignment(StringAlignmentCenter);f.SetTrimming(StringTrimmingEllipsisCharacter);g.DrawString(value.c_str(),int(value.size()),font.get(),r,&f,&b);}
