PhotoEditorResult showPhotoEditor(HWND owner,std::shared_ptr<Picture> picture,const fs::path& original,const PhotoEditorStyle& style){if(!picture)return {};Editor editor;editor.style=style;editor.originalPath=original;editor.original=editor.picture=picture;editor.resetAnchors();return runEditor(owner,editor);}
bool photoEditorSelfTest(HWND owner){Editor editor;editor.testing=true;auto fixture=std::make_shared<Picture>();fixture->width=fixture->originalW=40;fixture->height=fixture->originalH=30;fixture->pixels.resize(40*30*4,255);for(unsigned y=7;y<23;++y)for(unsigned x=10;x<30;++x){auto n=(y*40+x)*4;fixture->pixels[n]=BYTE(x*3);fixture->pixels[n+1]=BYTE(y*3);fixture->pixels[n+2]=220;}for(unsigned c=0;c<3;++c)fixture->pixels[(15*40+20)*4+c]=0;editor.originalPath=editor.testFiles.path/L"editor-source.png";if(!exportPicture(*fixture,editor.testFiles.path/L"untouched.png",editor.originalPath,ExportFormat::PNG,0,false))return false;editor.original=editor.picture=fixture;editor.resetAnchors();auto result=runEditor(owner,editor);return editor.testPassed&&editor.testStage==14&&result.picture&&fs::exists(result.saved);}
